source='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return out
    frame = counts.most_common(1)[0][0]
    seen = set()
    components = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, frame) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            components.setdefault(color, []).append(cells)

    for color, groups in components.items():
        if len(groups) != 4:
            continue
        boxes = []
        for cells in groups:
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            boxes.append((min(rs), max(rs), min(cs), max(cs)))
        heights = {b[1]-b[0]+1 for b in boxes}
        widths = {b[3]-b[2]+1 for b in boxes}
        if len(heights) != 1 or len(widths) != 1:
            continue
        rows = sorted({(b[0]+b[1])//2 for b in boxes})
        cols = sorted({(b[2]+b[3])//2 for b in boxes})
        if len(rows) != 2 or len(cols) != 2:
            continue
        by_center = {((b[0]+b[1])//2, (b[2]+b[3])//2): b for b in boxes}
        if set(by_center) != {(r,c) for r in rows for c in cols}:
            continue
        # Bridge aligned colored blocks, preserving intervening objects.
        for r in rows:
            left = by_center[(r, cols[0])]
            right = by_center[(r, cols[1])]
            for y in range(left[0], left[1]+1):
                for x in range(left[3]+1, right[2]):
                    if out[y][x] == 0:
                        out[y][x] = color
        for c in cols:
            top = by_center[(rows[0], c)]
            bottom = by_center[(rows[1], c)]
            for x in range(top[2], top[3]+1):
                for y in range(top[1]+1, bottom[0]):
                    if out[y][x] == 0:
                        out[y][x] = color
    return out
'''
